import {escapeHTML as h} from './model.js?v=0.31.0';
import {careerCandidates,selectedFollowUps} from './exploration.js?v=0.31.0';
import {getCareerFacts} from './occupation-data.js?v=0.31.0';

const esc=h;
const link=(href,label)=>`<a href="${esc(href)}">${esc(label)}</a>`;
const field=(name,label,value='',attrs='')=>`<div class="exploration-field"><label for="explore-${name}">${esc(label)}</label><input id="explore-${name}" data-exploration-field="${esc(name)}" maxlength="${name==='context.nomination'?200:120}" value="${esc(value)}" ${attrs}></div>`;
const area=(name,label,value='',max=1000)=>`<div class="exploration-field"><label for="explore-${name}">${esc(label)}</label><textarea id="explore-${name}" data-exploration-field="${esc(name)}" maxlength="${max}">${esc(value)}</textarea></div>`;

function careerCard(row,state){
 const x=state.exploration||{},id=esc(row.id),facts=row.career,selected=row.selected||x.savedCareers?.includes(row.id)||x.careerChoices?.[row.id]==='explore',compared=x.compareCareers?.includes(row.id);
 const task=facts.tasks?.[0];
 return `<article class="exploration-career"><div class="exploration-career-head"><span class="exploration-kicker">${esc(row.category==='editorial'?'Fieldguide editorial connection':row.category==='student-choice'?'Your choice':row.category==='official-return'?'Official provider-returned career':row.category==='related'?'Related occupation':'Browse possibility')}</span><h3>${esc(facts.title)}</h3><p>${esc(facts.summary||'Explore this occupation and decide what you would like to learn.')}</p></div>${task?`<div class="exploration-task"><strong>One task to investigate</strong><p>${esc(task.text)}</p><small>${link(task.source||facts.url||facts.sourceURL,'Occupation source')}</small></div>`:''}${row.evidence.length?`<div class="exploration-evidence"><strong>Why it is here</strong><ul>${row.evidence.map(e=>`<li>${esc(e.label)} <span>${esc(e.reference)}</span></li>`).join('')}</ul></div>`:`<p class="exploration-unknown">A browse possibility, not a personalized match.</p>`}${row.unknowns.length?`<p class="exploration-unknown">${row.unknowns.map(esc).join(' ')}</p>`:''}<div class="exploration-actions"><label class="career-choice-label">My choice<select data-career-choice="${id}"><option value="" ${!x.careerChoices?.[row.id]?'selected':''}>Not decided</option><option value="explore" ${x.careerChoices?.[row.id]==='explore'?'selected':''}>Explore this career</option><option value="questions" ${x.careerChoices?.[row.id]==='questions'?'selected':''}>I have questions</option><option value="later" ${x.careerChoices?.[row.id]==='later'?'selected':''}>Set aside for now</option></select></label><button type="button" class="secondary" data-career-save="${id}" aria-pressed="${selected}">${selected?'Saved':'Save'}</button><button type="button" class="secondary" data-career-compare="${id}" aria-pressed="${Boolean(compared)}">${compared?'In comparison':'Compare'}</button><a class="exploration-link" href="#/career/${id}">Open career details</a><a class="exploration-link" href="#/career-reflection/${id}">Reflect on this work</a></div><div class="exploration-reasons"><strong>Try a small next step: ${esc(row.experiment.title)}</strong><p>${esc(row.experiment.detail)}</p>${row.experiment.notice?`<small>${esc(row.experiment.notice)}</small>`:''}</div></article>`;
}

export function journeyPage(state){
 const x=state.exploration||{},journey=x.journey||'';
 const rows=careerCandidates(state);
 const paths=[['quick','Quick exploration','Start with a brief browse and a few optional reflections. You can also use a suitable result you already have.'],['full','Full exploration','Use the longer paper form or a suitable Short Form result you already have. Projects and context can support a counselor conversation.']];
 const routes=[['college','College'],['apprenticeship','Apprenticeship'],['certificate','Certificate or training'],['work','Work experience'],['military','Military'],['not-sure','Not sure yet']];
 return `<section class="exploration-page"><header class="exploration-intro"><span class="exploration-kicker">DISCOVER · YOUR WAY</span><h1>Choose a way to explore</h1><p>You can start without an assessment. These journeys organize exploration; optional reflections never change standardized scores.</p></header><div class="journey-options">${paths.map(([id,title,copy])=>`<article class="journey-option ${journey===id?'chosen':''}"><span class="exploration-kicker">${id==='quick'?'ABOUT 30 ITEMS':'ABOUT 60 ITEMS'}</span><h2>${esc(title)}</h2><p>${esc(copy)}</p><button type="button" data-exploration-field="journey" data-value="${id}" aria-pressed="${journey===id}">${journey===id?'Selected':'Choose this journey'}</button></article>`).join('')}</div><div class="exploration-callout"><h2>Assessment choices</h2><p>The official online Mini-IP is 30 items. The 60-item paper Short Form is available to print. An automated 60-item online administration requires a supported provider; this site does not administer one.</p><div class="exploration-linkrow">${link('https://onetinterestprofiler.org/','Open official 30-item online Mini-IP')}${link('https://www.onetcenter.org/dl_tools/ipsf/Interest_Profiler.pdf','Open official 60-item paper Short Form')}${link('#/results','Enter or review an existing result')}</div><p class="exploration-note">Keep the exact form, source, scale and score representation with any result. You do not need to take both forms.</p></div><section class="exploration-context"><div><span class="exploration-kicker">OPTIONAL PLANNING CONTEXT</span><h2>What would help make this useful?</h2><p>Share only what you want. These answers support planning and do not predict ability or success.</p></div><div class="exploration-context-grid">${field('context.language','Language or accessibility needs',x.context?.language||'')}${field('context.educationLocation','Where might you study or work?',x.context?.educationLocation||'','placeholder="Optional location or jurisdiction"')}<fieldset class="exploration-routes"><legend>Routes you want to investigate</legend>${routes.map(([id,label])=>`<label><input type="checkbox" data-exploration-route="${id}" ${(x.context?.routes||[]).includes(id)?'checked':''}>${esc(label)}</label>`).join('')}</fieldset>${area('context.costConcerns','Cost questions or concerns',x.context?.costConcerns||'')}${area('context.supportNeeds','Support that would help you explore',x.context?.supportNeeds||'')}${field('context.nomination','A career or subject you want included',x.context?.nomination||'')}</div></section><section class="exploration-results"><div class="exploration-section-head"><span class="exploration-kicker">POSSIBILITIES TO INVESTIGATE</span><h2>Specific work, open questions</h2><p>Student choices and editorial connections are labeled. This list is not a rank, aptitude score, admission prediction, or career-success estimate.</p></div><div class="exploration-career-list">${rows.map(row=>careerCard(row,state)).join('')}</div></section></section>`;
}

export function careerReflectionPage(id,state){
 const career=getCareerFacts(id);if(!career)return `<section class="exploration-page"><h1>Career not found</h1><p>This occupation is no longer available in the reviewed collection.</p><a href="#/journey">Return to exploration</a></section>`;
 const x=state.exploration||{},answers=x.followUps?.[id]||{},prompts=selectedFollowUps(state,id);
 return `<section class="exploration-page career-reflection"><header class="exploration-intro"><span class="exploration-kicker">OPTIONAL · NOT SCORED</span><h1>Reflect on ${esc(career.title)}</h1><p>These original prompts help you notice questions about real work. You can disagree, skip a prompt, or say you have not tried it. Your answers do not change interest or ability results.</p></header><article class="reflection-career-fact"><h2>Work to explore</h2><p>${esc(career.summary)}</p>${career.tasks?.length?`<ul>${career.tasks.slice(0,3).map(t=>`<li>${esc(t.text)} ${link(t.source,'Source')}</li>`).join('')}</ul>`:''}<p class="exploration-note">Occupation descriptions are evidence about the work, not claims about you.</p></article><div class="reflection-prompts">${prompts.map((p,i)=>{const a=answers[p.id]||{};return `<fieldset class="reflection-prompt"><legend><span>${i+1}</span>${esc(p.title)}</legend><p>${esc(p.text)}</p><small class="prompt-condition">${esc(p.condition)}</small><label for="response-${esc(p.id)}">Your thoughts · optional</label><textarea id="response-${esc(p.id)}" data-career-id="${esc(id)}" data-follow-up="${esc(p.id)}" data-follow-up-field="response" maxlength="2000">${esc(a.response||'')}</textarea><div class="reflection-choice-row"><label>Status<select data-career-id="${esc(id)}" data-follow-up="${esc(p.id)}" data-follow-up-field="status"><option value="" ${!a.status?'selected':''}>Choose if useful</option><option value="answered" ${a.status==='answered'?'selected':''}>I answered</option><option value="not-tried" ${a.status==='not-tried'?'selected':''}>I have not tried this</option><option value="unsure" ${a.status==='unsure'?'selected':''}>I am not sure yet</option><option value="skipped" ${a.status==='skipped'?'selected':''}>Skip for now</option></select></label><label>Exposure<select data-career-id="${esc(id)}" data-follow-up="${esc(p.id)}" data-follow-up-field="exposure"><option value="" ${!a.exposure?'selected':''}>Not recorded</option><option value="new" ${a.exposure==='new'?'selected':''}>New to me</option><option value="some" ${a.exposure==='some'?'selected':''}>Tried a little</option><option value="often" ${a.exposure==='often'?'selected':''}>Tried several times</option></select></label><label>Current confidence<select data-career-id="${esc(id)}" data-follow-up="${esc(p.id)}" data-follow-up-field="confidence"><option value="" ${!a.confidence?'selected':''}>Not recorded</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${a.confidence===n?'selected':''}>${n} · ${['','Not confident yet','A little confident','Somewhat confident','Very confident','Ready to show someone'][n]}</option>`).join('')}</select></label></div><label for="evidence-${esc(p.id)}">Experience or evidence · optional</label><textarea id="evidence-${esc(p.id)}" data-career-id="${esc(id)}" data-follow-up="${esc(p.id)}" data-follow-up-field="evidence" maxlength="1000" placeholder="A course, project, conversation, or experience">${esc(a.evidence||'')}</textarea><div class="prompt-footer"><small>Recorded locally with the date of your response.</small><button type="button" class="secondary" data-follow-up-action="skip" data-career-id="${esc(id)}" data-follow-up="${esc(p.id)}">Skip this prompt</button></div></fieldset>`;}).join('')}</div><section class="exploration-context"><h2>Keep your own view</h2><p>What would you like to ask about this career? You can say the description does not sound like you.</p>${area(`careerQuestions.${id}`,'My question or disagreement',x.careerQuestions?.[id]||'')}${area(`careerNotes.${id}`,'My notes',x.careerNotes?.[id]||'')}</section><p class="exploration-back"><a href="#/journey">Back to career possibilities</a></p></section>`;
}
